/// Registers a prepared local NCNN import using the same exact engine and
/// engine installation lock as catalog downloads. Model bytes were copied
/// and checked by LegacySherpaNcnn before entering this method.
pub(crate) fn registerLegacyNcnnModel(
    &self,
    installed: InstalledLocalModel,
) -> Result<(), String> {
    if installed.manifest != LocalModelCatalog::oldAssistanceSherpaNcnnStt() {
        return Err("local NCNN model does not match the original catalog".into());
    }
    self.requirePlatformCompatibleModel(&installed.manifest)?;
    let requirement = installed.manifest.engineRequirement.as_ref()
        .ok_or("local NCNN engine requirement is missing")?;
    let engine_manifest = self.catalogEngine(&requirement.engineId, &requirement.version)?;
    let target = LocalPlatformTarget::current()?;
    let artifact = engine_manifest.artifactForTarget(&target)
        .ok_or("local NCNN engine is unavailable on this platform")?.clone();
    let lock = engineInstallLock(engineInstallLockKey(&self.runtimeRoot, &engine_manifest, &target))?;
    let _guard = lock.lock().map_err(|error| format!("NCNN engine installation lock: {error}"))?;
    let installer = self.engineInstaller()?;
    let snapshot = installer.readRegistry().map_err(errorString)?;
    if snapshot.getInstalledEngine(&requirement.engineId, &requirement.version, &target)
        .is_some_and(|existing| existing.artifact == artifact) {
        installer.verifyInstalledEngine(&requirement.engineId, &requirement.version, &target,
            currentTimeMillis()).map_err(errorString)?;
    } else {
        installer.install(
            LocalEngineInstallRequest { manifest: engine_manifest, target, installedAtMs: currentTimeMillis() },
            HttpDownloadControl::new(), Arc::new(|_| {}),
        ).map_err(errorString)?;
    }
    let store = self.registryStore()?;
    let mut registry = store.read().map_err(errorString)?;
    registry.upsert(installed);
    store.write(&registry).map_err(errorString)
}

